        ("M46 README.md: an ancestor's own map line dropped, its `.verify.sh` line left", before,
         after, shard, claude, None, SAME, m46, lineage, provenance),
        ("M47 every copy AND the declaration open TWO clauses below (shape)", before, m47_a,
         m47_s, m47_c, {"POINTER": m47_p, "BANNER": m47_b, "ROUTING": m47_r}, SAME, reach, lineage, provenance),
        ("M48 an ancestor shard git knows no add-commit for", before, after, shard, claude,
         None, SAME, reach, m48, provenance),
        ("M49 a file L8 must read is unreadable", before, after, shard, claude, None, SAME,
         m49, lineage, provenance),
        ("M50 a declared required string reworded, nothing else disturbed", before, after, shard,
         claude, None, SAME, m50, lineage, provenance),
        # --- the nine this trim adds. M51 keeps the NARROWED b3 reachable; M52 reaches an arm the
        #     fourth trim shipped unmutated; M53-M59 are L10's and L11's.
        ("M51 a front-matter line COPIED into the banner and left in place upstream (b3 alone)",
         before, after, m51_s, claude, {"BANNER": m51_b}, SAME, reach, lineage, provenance),
        ("M52 an ANCESTOR shard's filename typo'd in the declaration and EVERY copy (L5/4 alone)",
         before, m52_a, m52_s, m52_c, {"POINTER": m52_p, "BANNER": m52_b, "ROUTING": m52_r},
         SAME, m52_reach, lineage, provenance),
        ("M53 an ancestor PROOF's declared freeze commit holds no such path", before, after,
         shard, claude, None, SAME, reach, lineage, m53),
        ("M54 an ancestor PROOF deleted from the working tree", before, after, shard, claude,
         None, SAME, reach, lineage, m54),
        ("M55 an ancestor PROOF truncated on disk after its session froze it", before, after,
         shard, claude, None, SAME, reach, lineage, m55),
        ("M56 the retention TRIGGER relaxed so this trim should not have fired", before, after,
         shard, claude, {"POLICY": m56_pol}, SAME, reach, lineage, provenance),
        ("M57 the retention TARGET tightened below what the cut actually achieved", before, after,
         shard, claude, {"POLICY": m57_pol}, SAME, reach, lineage, provenance),
        ("M58 the retention FLOOR raised above the number of records retained", before, after,
         shard, claude, {"POLICY": m58_pol}, SAME, reach, lineage, provenance),
        ("M59 CLAUDE.md no longer states the trigger this assertion enforces", before, after,
         shard, m59_c, None, SAME, reach, lineage, provenance),
    ]
    bad = []
    for name, b, a, s, c, decl, disk, rch, lin, prov in mutants:
        # A mutant that does not name a disk state gets an untampered one: its own shard.
        d = s if disk is SAME else disk
        # The REAL sha, never a stand-in: L5/4 reads the ancestor shards through it, and a fake
        # one makes every one of them unreadable — which would "catch" every mutant by breaking
        # the proof rather than by detecting the mutation. L7, L9 and L10 stay reachable regardless
        # because their applicability comes from `d`, `lin` and `prov`, not from `sha`.
        fails, _ = check(b, a, s, c, sha, d, rch, lin, prov, decl)
        if not fails:
            bad.append(name)
            print("  SURVIVED  %s" % name)
        else:
            # EVERY assertion that fires, not just the first: it must stay visible which assertion
            # is doing the work. A reader who thinks L3 is an independent second opinion on L1 is
            # mistaken — and M16-M59 are the forty-four that prove L4-L11 are not either.
            codes = sorted({f.split(":")[0].split(" (")[0] for f in fails})
            print("  caught    %-74s -> %s" % (name, ", ".join(codes)))
    if bad:
        print("\nSELF-TEST FAILED: %d mutant(s) survived. This proof cannot be trusted." % len(bad))
        sys.exit(2)
    print("\nSELF-TEST OK: all %d mutants caught. Losing a byte fails this proof; so does editing"
          % len(mutants))
    print("one, skipping any declared correction, making an undeclared one, letting a declaration")
    print("go stale, sliding the cut point by one record, mis-stating where a session lives even")
    print("when every copy agrees, leaving a gap or an overlap in the routing table, editing the")
    print("shard's banner, pasting a front-matter line into it, touching ANY shard OR ANY ancestor")
    print("PROOF on disk after the commit that froze it, leaving README.md, PROJECT_CONVENTIONS.md,")
    print("BACKLOG.md or CLAUDE.md describing the shard set that existed before, or relaxing the")
    print("retention rule this cut exists to satisfy.")


before, after, shard, claude, source, sha, disk, reach, lineage, provenance = artifacts()

if "--self-test" in sys.argv:
    print("--self-test: mutating the artifacts and asserting each mutation is caught.\n")
    self_test(before, after, shard, claude, sha, reach, lineage, provenance)
    sys.exit(0)

fails, (br, ar, sr) = check(before, after, shard, claude, sha, disk, reach, lineage, provenance)
have = Counter(ar) + Counter(sr)
added = len(list((have - Counter(br)).elements()))
note = noleak_note(zones(before)[0], sr)

print("source : %s" % source)
print("grammar: heading /^### What Session \\S+ Did$/ ; footer_mode=none (asserted) ; transform=none")
print("records: %d before = %d retained + %d archived; added by the trim commit: %d"
      % (len(br), len(ar), len(sr), added))
print("cut key: retained %s | archived %s   (hand-declared, checked by L4 and L5)"
      % (list(CUT_RETAINED), list(CUT_ARCHIVED)))
print("routing: %d clauses, checked in 3 copies (live pointer, shard banner, CLAUDE.md) and"
      % len(ROUTING))
print("         anchored against the record ids actually in each file it names")
print("reach  : %d copies L5 does not check — three no proof could see at all, plus CLAUDE.md's"
      % len(REACH))
print("         prose around the table L5 has always read (%s)"
      % ", ".join(p for p, _r, _f in REACH))
print("lineage: %d ancestor shard(s) held against their own add-commits" % len(lineage))
print("provena: %d ancestor proof(s) held against hand-declared freeze commits" % len(provenance))
print("policy : fired above %d lines, landed at %d (target %d), retained %d records (floor %d)"
      % (POLICY[0], len(after.splitlines()), POLICY[1], len(ar), POLICY[2]))
print("front  : pointer insertion + %d declared substitutions, all checked by exact equality"
      % len(FRONT_SUBST))
print("checked: L0, L1, L2/front-matter, L3, L4, L5, L6, L7, L8, L9, L10, L11    "
      "<- L2/footer absent: inapplicable, no footer zone")
print("b3 note: NARROWED to the banner at this trim. %d front-matter line(s) occur inside the"
      % len(note))
print("         archived RECORDS and would have been flagged by the inherited predicate.")
if any(f.startswith("L1") for f in fails):
    # The narrowing's whole justification is that L1 pins these bytes. On the one run where L1 is
    # RED that justification is void, and printing it as a fact — three lines above the FAIL block
    # — would tell the reader the removed check was redundant exactly when it was not.
    print("         *** L1 IS RED ON THIS RUN. These lines are NOT pinned, so the half this trim")
    print("         *** narrowed away would have carried information here. Treat each as a")
    print("         *** CANDIDATE LEAK until L1 is green again.")
else:
    print("         L1 is green, so each is pinned byte-for-byte and none of them can be a leak.")
print("         Nothing is hidden:")
for i, s in note:
    print("           front-matter line %d: %s" % (i, s[:120]))
if not note:
    print("           (none on this cut)")
if sha is None:
    print("         L7 inapplicable: the trim is not committed yet, so there is no frozen blob to")
    print("         compare the working tree against. It becomes live at the trim commit. L9 and")
    print("         L10 are applicable already — their operands were frozen by earlier sessions.")

if fails:
    print("\nFAIL for %s:" % SHARD)
    for f in fails:
        print("  " + f)
    sys.exit(1)

print("\nOK: %s hold for %s" % ("L0-L11" if sha else "L0-L6, L8-L11 (L7 inapplicable)", SHARD))
print("    Every byte of the pre-trim records zone is still present, in the right file, unedited,")
print("    in order, and on the declared side of the declared boundary; all three copies of the")
print("    routing table agree with that boundary AND with what the files they name contain; the")
print("    shard's banner is the declared text and carries no leaked front matter; README.md,")
print("    PROJECT_CONVENTIONS.md, BACKLOG.md and CLAUDE.md describe the shard set that now")
print("    exists; every earlier shard AND every earlier proof on disk is still the file its own")
print("    session froze; and this cut obeyed the retention rule CLAUDE.md declares.")
if sha:
    print("    The shard on disk is still the shard that was committed at %s." % sha[:7])
else:
    print("    NOTHING is claimed about THIS shard on disk: L7 has no frozen blob to compare it")
    print("    against until the trim is committed. Re-run after committing.")
print("    It says NOTHING about whether the boundary was wisely chosen BEYOND the three numbers")
print("    L11 enforces, nor whether any record's content is true — a human reads that once. It")
print("    does not re-prove the S216, S220, S224 or S227 cuts: each has its own proof, pinned to")
print("    its own cut key and its own commit. Run those four as well. A green proof never")
print("    --self-test'ed proves less than it appears to.")
PYEOF
